long toL(def v) { if (v == null) return 0L; String s = v.toString().trim(); if (s.length() == 0) return 0L; try { return Long.parseLong(s); } catch (Exception e) {} try { return (long)Double.parseDouble(s); } catch (Exception e) {} return 0L; }
def idx = ctx.remove('idx');
def project = ctx.remove('project');
long dsize = toL(ctx.remove('dsize'));
long docs = toL(ctx.remove('docs'));
long itime = toL(ctx.remove('itime'));
long itotal = toL(ctx.remove('itotal'));
long qtime = toL(ctx.remove('qtime'));
long qtotal = toL(ctx.remove('qtotal'));
if (idx == null || project == null) { throw new IllegalArgumentException('idx and project are required'); }
Map store = ['size_in_bytes': dsize, 'total_data_set_size_in_bytes': dsize];
Map total = ['store': store, 'indexing': ['index_time_in_millis': itime, 'index_total': itotal], 'search': ['query_time_in_millis': qtime, 'query_total': qtotal], 'docs': ['count': docs]];
Map primaries = ['store': ['size_in_bytes': dsize, 'total_data_set_size_in_bytes': dsize]];
ctx.elasticsearch = ['cluster': ['name': project], 'index': ['name': idx, 'tier': 'serverless', 'total': total, 'primaries': primaries]];
ctx.metricset = ['name': 'index'];
ctx.source_type = 'serverless_cat_indices';
